/**
 * Mirrors the messenger's logic (`apps/messenger/src/lib`) into the NSH app as `app/src/m/`, so the
 * NSH screens use the same stores, reducers, API client and copy as the Svelte ones:
 *
 * - A module that runs as it is (no DOM, no Svelte runes in its import closure) becomes a one-line
 *   re-export of the original (`// Generated by scripts/port-messenger.ts`), rewritten every run.
 * - A rune store (`*.svelte.ts`), and a module whose imports reach one, becomes a port: its source
 *   with the rune syntax rewritten onto `app/src/lib/reactive.ts` (`// Ported from …`). A port is
 *   written once and then edited by hand; a later run leaves it alone unless `--force <rel>`.
 * - What cannot run here (Monaco, pdfjs, xterm, the remote page transport, test kits) is left out.
 *
 *   bun apps/desktop-nsh/scripts/port-messenger.ts [--check] [--force <rel> …]
 *
 * `--check` writes nothing and exits 1 when a generated file is missing or stale (CI runs it).
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, posix, relative, resolve, sep } from "node:path";
import ts from "typescript";

const root = resolve(import.meta.dir, "..");
const lib = resolve(root, "../messenger/src/lib");
const mirror = join(root, "app", "src", "m");
const reactive = join(root, "app", "src", "lib", "reactive.ts");
const GENERATED = "// Generated by scripts/port-messenger.ts from apps/messenger/src/lib; do not edit.";
/** A relative path with forward slashes on every platform: how `EXCLUDE` names files and imports spell them. */
const slashed = (path: string) => path.split(sep).join("/");
const PORTED = "// Ported from apps/messenger/src/lib by scripts/port-messenger.ts; edited here since.";
/** The original's hash a port was made from: `--check` fails once the original moves on. */
const SOURCE = "// Source: ";

function hash(text: string): string {
  return new Bun.CryptoHasher("sha256").update(text).digest("hex").slice(0, 16);
}

/** Left out: they need the DOM, a web worker or Svelte components, or are test kits. */
const EXCLUDE = [
  // pdf.js's viewer; PDF pages come from hayro here (app/native).
  /^overlays\/pdf-(pages|find)\.svelte\.ts$/,
  /^remote\/PairingScreen/,
  /(^|\/)test-[^/]*\.ts$/,
  /\.test\.ts$/,
  /\.d\.ts$/,
  /^monaco/,
  /^overlays\/artifact-monaco\.ts$/,
  /^overlays\/monaco-/,
  /^overlays\/pdfjs\.ts$/,
  /^overlays\/task-trace-test-kit\.ts$/,
  /^calendar\/calendar-entry\.ts$/,
  /^overlays\/novnc-loader\.ts$/,
  /^highlight-mount\.ts$/,
  // HTML from Markdown through DOMPurify; NSH's TextView reads Markdown itself.
  /^markdown\.ts$/,
];

const check = process.argv.includes("--check");
const forced = new Set<string>();
for (let i = 0; i < process.argv.length; i++) if (process.argv[i] === "--force" && process.argv[i + 1]) forced.add(process.argv[i + 1]!);

function walk(dir: string, out: string[] = []): string[] {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) walk(path, out);
    else if (entry.name.endsWith(".ts")) out.push(slashed(relative(lib, path)));
  }
  return out;
}

const all = walk(lib).filter((rel) => !EXCLUDE.some((re) => re.test(rel))).sort();
const sources = new Map(all.map((rel) => [rel, readFileSync(join(lib, rel), "utf8")]));

function relativeImports(rel: string): string[] {
  const text = sources.get(rel) ?? "";
  const file = ts.createSourceFile(rel, text, ts.ScriptTarget.Latest, true);
  const found: string[] = [];
  const visit = (node: ts.Node) => {
    if ((ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) && node.moduleSpecifier && ts.isStringLiteral(node.moduleSpecifier)) {
      const typeOnly = ts.isImportDeclaration(node) ? node.importClause?.isTypeOnly : node.isTypeOnly;
      const spec = node.moduleSpecifier.text;
      if (!typeOnly && spec.startsWith(".")) found.push(posix.join(posix.dirname(rel), spec));
    }
    ts.forEachChild(node, visit);
  };
  visit(file);
  return found;
}

// A module needs a port when it is a rune store or reaches one through value imports.
const needsPort = new Map<string, boolean>();
function porting(rel: string, seen = new Set<string>()): boolean {
  const known = needsPort.get(rel);
  if (known !== undefined) return known;
  if (seen.has(rel)) return false;
  seen.add(rel);
  let result = rel.endsWith(".svelte.ts");
  if (!result) for (const dep of relativeImports(rel)) if (sources.has(dep) && porting(dep, seen)) result = true;
  needsPort.set(rel, result);
  return result;
}

function shim(rel: string): string {
  const target = slashed(relative(dirname(join(mirror, rel)), join(lib, rel)));
  const hasDefault = /export\s+default\b/.test(sources.get(rel) ?? "");
  return `${GENERATED}\nexport * from "${target}";\n${hasDefault ? `export { default } from "${target}";\n` : ""}`;
}

type Edit = { pos: number; end: number; text: string };
const RUNES = new Set(["$state", "$state.raw", "$derived", "$derived.by"]);

/** The store's source with its runes on `reactive.ts`; `manual` lists what needs a hand. */
function port(rel: string): { text: string; manual: string[] } {
  const text = sources.get(rel)!;
  const file = ts.createSourceFile(rel, text, ts.ScriptTarget.Latest, true);
  const edits: Edit[] = [];
  const used = new Set<string>();
  const manual: string[] = [];
  const at = (node: ts.Node) => `${rel}:${file.getLineAndCharacterOfPosition(node.getStart()).line + 1}`;

  const visit = (node: ts.Node) => {
    if (ts.isPropertyDeclaration(node) && node.initializer && ts.isCallExpression(node.initializer)) {
      const call = node.initializer;
      const callee = call.expression.getText(file);
      if (RUNES.has(callee)) {
        const name = node.name.getText(file);
        const store = name.startsWith("#") ? `${name}$s` : `#${name}$s`;
        const mods = (node.modifiers ?? [])
          .filter((m) => m.kind !== ts.SyntaxKind.ReadonlyKeyword)
          .map((m) => m.getText(file))
          .join(" ");
        const prefix = mods ? `${mods} ` : "";
        const staticPrefix = mods.includes("static") ? "static " : "";
        const declared = node.type?.getText(file);
        const typeArgs = call.typeArguments?.map((t) => t.getText(file)).join(", ");
        const typeParam = declared ?? typeArgs;
        const generic = typeParam ? `<${typeParam}>` : "";
        const args = call.arguments.map((a) => a.getText(file)).join(", ");
        const returnType = typeParam ? `: ${typeParam}` : "";
        let replacement: string;
        if (callee === "$state" || callee === "$state.raw") {
          const fn = callee === "$state" ? "state" : "rawState";
          used.add(fn);
          replacement =
            `${staticPrefix}${store} = ${fn}${generic}(${args});\n` +
            `\t${prefix}get ${name}()${returnType} { return this.${store}.get(); }\n` +
            `\t${prefix}set ${name}(value${typeParam ? `: ${typeParam}` : ""}) { this.${store}.set(value); }`;
        } else {
          used.add("derived");
          const body = callee === "$derived" ? `() => (${args})` : args;
          replacement =
            `${staticPrefix}${store} = derived${generic}(${body});\n` +
            `\t${prefix}get ${name}()${returnType} { return this.${store}.get(); }`;
        }
        edits.push({ pos: node.getStart(file), end: node.getEnd(), text: replacement });
        return;
      }
    }
    // A module-level `const x = $state(v)` is never replaced, only changed in place: a deep proxy.
    if (
      ts.isVariableDeclaration(node) &&
      node.initializer &&
      ts.isCallExpression(node.initializer) &&
      ts.isVariableDeclarationList(node.parent) &&
      (node.parent.flags & ts.NodeFlags.Const) !== 0
    ) {
      const call = node.initializer;
      const callee = call.expression.getText(file);
      if (callee === "$state" || callee === "$state.raw") {
        const typeArgs = call.typeArguments?.map((t) => t.getText(file)).join(", ");
        const args = call.arguments.map((a) => a.getText(file)).join(", ");
        if (callee === "$state") {
          used.add("deep");
          edits.push({ pos: call.getStart(file), end: call.getEnd(), text: `deep${typeArgs ? `<${typeArgs}>` : ""}(${args})` });
        } else {
          edits.push({ pos: call.getStart(file), end: call.getEnd(), text: typeArgs ? `(${args}) as ${typeArgs}` : args });
        }
        return;
      }
    }
    if (ts.isCallExpression(node)) {
      const callee = node.expression.getText(file);
      if (callee === "$effect" || callee === "$effect.pre") {
        used.add("effect");
        edits.push({ pos: node.expression.getStart(file), end: node.expression.getEnd(), text: "effect" });
      } else if (callee === "$state.snapshot") {
        used.add("snapshot");
        edits.push({ pos: node.expression.getStart(file), end: node.expression.getEnd(), text: "snapshot" });
      } else if (callee.startsWith("$state") || callee.startsWith("$derived") || callee.startsWith("$effect")) {
        manual.push(`${at(node)} ${callee}(…) outside a class field`);
      }
    }
    if (ts.isImportDeclaration(node) && ts.isStringLiteral(node.moduleSpecifier) && node.moduleSpecifier.text === "svelte") {
      const spec = slashed(relative(dirname(join(mirror, rel)), reactive)).replace(/\.ts$/, "");
      edits.push({ pos: node.moduleSpecifier.getStart(file), end: node.moduleSpecifier.getEnd(), text: `"${spec.startsWith(".") ? spec : `./${spec}`}"` });
    } else if (ts.isImportDeclaration(node) && ts.isStringLiteral(node.moduleSpecifier) && /^svelte\//.test(node.moduleSpecifier.text)) {
      manual.push(`${at(node)} imports ${node.moduleSpecifier.text}`);
    } else if (ts.isImportDeclaration(node) && ts.isStringLiteral(node.moduleSpecifier) && node.moduleSpecifier.text.endsWith(".svelte")) {
      manual.push(`${at(node)} imports a component ${node.moduleSpecifier.text}`);
    }
    ts.forEachChild(node, visit);
  };
  visit(file);

  let out = text;
  for (const edit of edits.sort((a, b) => b.pos - a.pos)) out = out.slice(0, edit.pos) + edit.text + out.slice(edit.end);
  if (used.size) {
    const spec = slashed(relative(dirname(join(mirror, rel)), reactive)).replace(/\.ts$/, "");
    const from = spec.startsWith(".") ? spec : `./${spec}`;
    out = `import { ${[...used].sort().join(", ")} } from "${from}";\n${out}`;
  }
  // The original's own relative imports resolve inside the mirror; the protocol through its alias.
  return { text: `${PORTED}\n${SOURCE}${hash(text)}\n${out}`, manual };
}

let stale = 0;
const manual: string[] = [];
const ported: string[] = [];
const expected = new Set<string>();
for (const rel of all) {
  const target = join(mirror, rel);
  expected.add(target);
  if (porting(rel)) {
    ported.push(rel);
    if (existsSync(target) && !forced.has(rel)) {
      const head = readFileSync(target, "utf8").split("\n", 3).find((line) => line.startsWith(SOURCE));
      const now = hash(sources.get(rel)!);
      if (head?.slice(SOURCE.length) !== now) {
        if (check) {
          stale++;
          console.error(`port behind its original: ${rel} (diff apps/messenger/src/lib/${rel}, then update the port and its Source line to ${now})`);
        } else if (!head) {
          // A port from before Source lines: it was made from the original as it is now.
          const body = readFileSync(target, "utf8").replace(`${PORTED}\n`, `${PORTED}\n${SOURCE}${now}\n`);
          writeFileSync(target, body);
        } else {
          console.warn(`port behind its original: ${rel}`);
        }
      }
      continue;
    }
    const result = port(rel);
    manual.push(...result.manual);
    if (check) {
      stale++;
      console.error(`missing port: ${rel}`);
      continue;
    }
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, result.text);
    continue;
  }
  const text = shim(rel);
  const current = existsSync(target) ? readFileSync(target, "utf8") : null;
  if (current !== null && !current.startsWith(GENERATED)) continue; // a hand port of a pure module
  if (current === text) continue;
  if (check) {
    stale++;
    console.error(`stale: ${rel}`);
    continue;
  }
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, text);
}

// Generated files whose original is gone.
function sweep(dir: string) {
  if (!existsSync(dir)) return;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) sweep(path);
    else if (!expected.has(path) && readFileSync(path, "utf8").startsWith(GENERATED)) {
      if (check) {
        stale++;
        console.error(`orphan: ${relative(mirror, path)}`);
      } else rmSync(path);
    }
  }
}
sweep(mirror);

// A test that loads every module of the mirror in the app's runtime, the globals first.
const loadTest = join(root, "app", "mirror.test.ts");
const modules = [...expected].map((path) => `./${slashed(relative(join(root, "app"), path))}`).sort();
const loadText =
  `${GENERATED}\n` +
  `// Every module of app/src/m loads in the app's runtime (QuickJS on the desktops).\n` +
  `import "./src/platform/install";\n` +
  modules.map((spec, i) => `import * as m${i} from "${spec}";`).join("\n") +
  `\nimport { expect, test } from "nsh/test";\n\n` +
  `test("every mirrored module loads", () => {\n` +
  `  const loaded = [${modules.map((_, i) => `m${i}`).join(", ")}];\n` +
  `  expect(loaded.length).toBe(${modules.length});\n` +
  `});\n`;
const currentLoad = existsSync(loadTest) ? readFileSync(loadTest, "utf8") : null;
if (currentLoad !== loadText) {
  if (check) {
    stale++;
    console.error("stale: app/mirror.test.ts");
  } else writeFileSync(loadTest, loadText);
}

console.log(`${all.length} modules: ${all.length - ported.length} re-exported, ${ported.length} ported`);
if (manual.length) console.log(`needs a hand:\n  ${manual.join("\n  ")}`);
if (check && stale) process.exit(1);
